// Декодер в ОДНОМ прогоне: ctrl/m0 — детектор (§144), далее таблица.
// Вызов ровно тот же, что у сервиса: unarchivedObjectOfClass:fromData:.
static BOOL bq39_one(Class clsV, const char *nm, const void *b, NSUInteger l) {
    NSData *d = [NSData dataWithBytes:b length:l];
    NSError *err = nil;
    id obj = nil;
    @try {
        obj = [NSKeyedUnarchiver unarchivedObjectOfClass:clsV fromData:d error:&err];
    } @catch (NSException *ex) {
        LOG("[bq39] %-9s THROW %s: %s", nm,
            ex.name.UTF8String ?: "?", ex.reason.UTF8String ?: "-");
        return NO;
    }
    if (obj) {
        LOG("[bq39] %-9s ACCEPT class=%s", nm, object_getClassName(obj));
        return YES;
    }
    LOG("[bq39] %-9s REJECT code=%ld err=%s", nm, (long)err.code,
        err.localizedDescription.UTF8String ?: "-");
    return NO;
}

static void p_bq39(void) {
    LOG("[bq39] v189 local LNValue decoder whitelist audit "
        "(§188 m1/m2 bytes were truncated -> rerun locally, valid bplists)");

    // Классы LNValue/LNEntityIdentifier/LNEntityIdentifierValueType
    // объявлены в LinkMetadata (svc.bin GOT 0x10005FE40/0x10005FE38).
    // dlopen по пути: dyld резолвит образ из кэша, файла на диске может не быть.
    static const char *kPaths[] = {
        "/System/Library/PrivateFrameworks/LinkMetadata.framework/LinkMetadata",
        "/System/Library/PrivateFrameworks/LinkServices.framework/LinkServices",
        "/System/Library/Frameworks/AppIntents.framework/AppIntents",
        NULL
    };
    for (int i = 0; kPaths[i]; i++) {
        void *h = dlopen(kPaths[i], RTLD_NOW | RTLD_LOCAL);
        const char *why = h ? "ok" : (dlerror() ?: "?");
        LOG("[bq39] dlopen %s -> %p (%s)", kPaths[i], h, why);
        if (h) break;
    }
    Class clsV = NSClassFromString(@"LNValue");
    Class clsE = NSClassFromString(@"LNEntityIdentifier");
    Class clsT = NSClassFromString(@"LNEntityIdentifierValueType");
    LOG("[bq39] classes LNValue=%p LNEntityIdentifier=%p LNEntityIdentifierValueType=%p",
        clsV, clsE, clsT);
    if (!clsV) {
        LOG("[bq39] CONTROL FAILED: LNValue not loaded in this sandbox — audit invalid");
        return;
    }

    // §144: детектор обязан показать срабатывание на заведомом входе ДО замера.
    if (!bq39_one(clsV, "ctrl", kFz35_C, sizeof(kFz35_C))) {
        LOG("[bq39] CONTROL FAILED: ctrl not decoded — abort");
        return;
    }
    if (!bq39_one(clsV, "m0", kFz38_M0, sizeof(kFz38_M0))) {
        LOG("[bq39] CONTROL FAILED: m0 round-trip not decoded — repack channel broken, abort");
        return;
    }

    int acc = 0, rej = 0;
    for (int i = 0; kFz39_var[i].nm; i++) {
        if (bq39_one(clsV, kFz39_var[i].nm, kFz39_var[i].b, kFz39_var[i].n))
            acc++;
        else
            rej++;
    }
    LOG("[bq39] SUMMARY variants accept=%d reject=%d "
        "(accept on *_dict = liberal slot => gadget surface OPEN)", acc, rej);
    LOG("[bq39] done");
}
