// bq40: тот же протокол, что bq39 (ctrl/m0-гейты §144 + таблица),
// но варианты — эксзотические классы в либеральные слоты (§198).
static void p_bq40(void) {
    LOG("[bq40] v190 fallback-set audit for liberal slots (§198: "
        "NSDictionary passed decode -> which classes does the gate admit?)");

    static const char *kPaths[] = {
        "/System/Library/PrivateFrameworks/LinkMetadata.framework/LinkMetadata",
        "/System/Library/PrivateFrameworks/LinkServices.framework/LinkServices",
        "/System/Library/Frameworks/AppIntents.framework/AppIntents",
        NULL
    };
    for (int i = 0; kPaths[i]; i++) {
        void *h = dlopen(kPaths[i], RTLD_NOW | RTLD_LOCAL);
        const char *why = h ? "ok" : (dlerror() ?: "?");
        LOG("[bq40] dlopen %s -> %p (%s)", kPaths[i], h, why);
        if (h) break;
    }
    Class clsV = NSClassFromString(@"LNValue");
    LOG("[bq40] classes LNValue=%p", clsV);
    if (!clsV) {
        LOG("[bq40] CONTROL FAILED: LNValue not loaded — audit invalid");
        return;
    }
    if (!bq39_one(clsV, "ctrl", kFz35_C, sizeof(kFz35_C))) {
        LOG("[bq40] CONTROL FAILED: ctrl not decoded — abort");
        return;
    }
    if (!bq39_one(clsV, "m0", kFz38_M0, sizeof(kFz38_M0))) {
        LOG("[bq40] CONTROL FAILED: m0 round-trip not decoded — abort");
        return;
    }

    int acc = 0, rej = 0;
    for (int i = 0; kFz40_var[i].nm; i++) {
        if (bq39_one(clsV, kFz40_var[i].nm, kFz40_var[i].b, kFz40_var[i].n))
            acc++;
        else
            rej++;  // THROW и REJECT различаются по префиксу строки выше
    }
    LOG("[bq40] SUMMARY accept=%d reject(incl throw)=%d "
        "(ex_object THROW = gate admits arbitrary classes)", acc, rej);
    LOG("[bq40] done");
}

// ===========================================================================
// V190 (p_bq41): спуф-тест классового гейта либеральных слотов.
//
// bq40: $classname=EXOTIC + $classes=[EXOTIC] -> REJECT 4864 всегда.
// Осталось различить: проверка по реальному классу (гаджеты закрыты,
// whitelist = контейнеры/plist-типы) или по массиву $classes из архива
