// bq41: декисивный тест после bq40 (эксзотика REJECT 4864):
// проверка гейта по реальному классу или по $classes из архива (спуф)?
static void p_bq41(void) {
    LOG("[bq41] v190 $classes-spoof test for liberal slots (bq40 exotic=REJECT; "
        "is the gate checked by real class or by archive $classes list?)");

    static const char *kPaths[] = {
        "/System/Library/PrivateFrameworks/LinkMetadata.framework/LinkMetadata",
        "/System/Library/PrivateFrameworks/LinkServices.framework/LinkServices",
        "/System/Library/Frameworks/AppIntents.framework/AppIntents",
        NULL
    };
    for (int i = 0; kPaths[i]; i++) {
        void *h = dlopen(kPaths[i], RTLD_NOW | RTLD_LOCAL);
        const char *why = h ? "ok" : (dlerror() ?: "?");
        LOG("[bq41] dlopen %s -> %p (%s)", kPaths[i], h, why);
        if (h) break;
    }
    Class clsV = NSClassFromString(@"LNValue");
    LOG("[bq41] classes LNValue=%p", clsV);
    if (!clsV) {
        LOG("[bq41] CONTROL FAILED: LNValue not loaded — audit invalid");
        return;
    }
    if (!bq39_one(clsV, "ctrl", kFz35_C, sizeof(kFz35_C))) {
        LOG("[bq41] CONTROL FAILED: ctrl not decoded — abort");
        return;
    }
    if (!bq39_one(clsV, "m0", kFz38_M0, sizeof(kFz38_M0))) {
        LOG("[bq41] CONTROL FAILED: m0 round-trip not decoded — abort");
        return;
    }

    int acc = 0, rej = 0;
    for (int i = 0; kFz41_var[i].nm; i++) {
        if (bq39_one(clsV, kFz41_var[i].nm, kFz41_var[i].b, kFz41_var[i].n))
            acc++;
        else
            rej++;  // THROW и REJECT различаются по префиксу строки выше
    }
    LOG("[bq41] SUMMARY accept=%d reject(incl throw)=%d "
        "(sp_null ACCEPT/THROW = spoof works = arbitrary instantiation)", acc, rej);
    LOG("[bq41] done");
}

