        endpoint = f(epCls, sysSel,
                     @"com.apple.extensionkitservice", @"TCCProxy", nil);
        LOG("[bq57] ep(sys-mach) = %s",
            endpoint ? [endpoint description].UTF8String : "(nil)");
    }
