                CFn2 cf = (CFn2)objc_msgSend;
                LOG("[bq57] -configure: begin (setInterface)");
                __block id ifaceRef = ifaceObj;
                cf(bsConn, cfgSel, ^(id cfg) {
                    LOG("[bq57] configure: cfg=%s",
                        cfg ? NSStringFromClass([cfg class]).UTF8String
                            : "(nil)");
