            typedef void (*AFn)(id, SEL);
            AFn af = (AFn)objc_msgSend;
            LOG("[bq57] -activate: begin (интерфейс задан)");
            af(bsConn, actSel);
            LOG("[bq57] -activate: вернулся");
        } else {
            LOG("[bq57] bsConn не отвечает activate");
        }
