        int fzBefore = bq18_count(db0, "SELECT count(*) FROM feedEntries "
                                       "WHERE entityId LIKE '%FZ29%'");
        char *err0 = NULL;
        int rc0 = sqlite3_exec(db0, "DELETE FROM feedEntries "
                               "WHERE entityId LIKE '%FZ29%'",
                               NULL, NULL, &err0);
        int after = bq18_count(db0, "SELECT count(*) FROM feedEntries");
        int fzAfter = bq18_count(db0, "SELECT count(*) FROM feedEntries "
                                      "WHERE entityId LIKE '%FZ29%'");
