    } @catch (NSException *e) {
        LOG("[bq35] SELF-TEST vA бросает как задумано: %s %s",
            e.name.UTF8String, e.reason ? e.reason.UTF8String : "");
    }
    @try {
        id o = [NSKeyedUnarchiver unarchiveObjectWithData:dB];
        LOG("[bq35] SELF-TEST vB(UID-250) НЕ бросил (obj=%@) — детектор НЕ взведён", o);
    } @catch (NSException *e) {
        LOG("[bq35] SELF-TEST vB бросает как задумано: %s %s",
            e.name.UTF8String, e.reason ? e.reason.UTF8String : "");
    }
    @try {
        id o = [NSKeyedUnarchiver unarchiveObjectWithData:dC];
        LOG("[bq35] SELF-TEST vC(оригинал) распаковался: %@ (в нашем процессе "
            "ожидался class-not-found — класса LNValue нет)", [o class]);
    } @catch (NSException *e) {
        LOG("[bq35] SELF-TEST vC бросил: %s %s (в нашем процессе это может быть "
            "class-not-found — байты валидны, контролирует только plant)",
            e.name.UTF8String, e.reason ? e.reason.UTF8String : "");
