    if (rollback) {
        BOOL bytesBack = YES;
        for (NSString *f in files) {
            NSString *bak = [bdir stringByAppendingPathComponent:
                f.lastPathComponent];
            struct stat fs2;
            if (stat(bak.fileSystemRepresentation, &fs2) != 0) continue;
