        if (getenv("FUZZ_DARTPROBE")) { p_dartprobe(); LOG("[probe13] dartprobe-only mode, stop"); return NULL; }
        if (getenv("FUZZ_S27DOWN")) { p_s27down(); LOG("[probe13] s27down-only mode, stop"); return NULL; }
